"use client";
import { useState, useEffect, use } from "react";
import Link from "next/link";
import { usePlan } from "@/context/PlanContext";
import { Clock, Flame, Star, PlusCircle, Bookmark, ArrowLeft } from "lucide-react";

export default function WorkoutDetails({ params }) {
  const { id } = use(params);
    const [workout, setWorkout] = useState(null);
      const [loading, setLoading] = useState(true);
        const { addToPlan, addToSaved } = usePlan();

          useEffect(() => {
              fetch(`https://api.abcz.workers.dev/api/fitlog/${id}`)
                    .then((res) => res.json())
                          .then((data) => {
                                  const item = Array.isArray(data) ? data[0] : data;
                                          setWorkout(item);
                                                  setLoading(false);
                                                        })
                                                              .catch((err) => {
                                                                      console.error(err);
                                                                              setLoading(false);
                                                                                    });
                                                                                      }, [id]);

                                                                                        if (loading) {
                                                                                            return (
                                                                                                  <div className="max-w-6xl mx-auto px-4 py-20 text-center text-neutral-400">
                                                                                                          <div className="inline-block animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-[#ccff00] mb-2"></div>
                                                                                                                  <p className="text-sm">Loading workout details...</p>
                                                                                                                        </div>
                                                                                                                            );
                                                                                                                              }

                                                                                                                                if (!workout) {
                                                                                                                                    return (
                                                                                                                                          <div className="max-w-6xl mx-auto px-4 py-20 text-center text-neutral-400">
                                                                                                                                                  <p className="text-lg font-bold mb-4">Workout not found</p>
                                                                                                                                                          <Link href="/" className="text-[#ccff00] underline text-sm">
                                                                                                                                                                    Back to Workouts
                                                                                                                                                                            </Link>
                                                                                                                                                                                  </div>
                                                                                                                                                                                      );
                                                                                                                                                                                        }

                                                                                                                                                                                          const defaultInstructions = [
                                                                                                                                                                                              "Position yourself firmly on the equipment with a stable base.",
                                                                                                                                                                                                  "Grip the handles or bar with full control and proper posture.",
                                                                                                                                                                                                      "Perform the movement with slow, controlled cadence.",
                                                                                                                                                                                                          "Exhale on exertion and return slowly to starting position."
                                                                                                                                                                                                            ];

                                                                                                                                                                                                              const instructionsList = Array.isArray(workout.instructions)
                                                                                                                                                                                                                  ? workout.instructions
                                                                                                                                                                                                                      : workout.instructions
                                                                                                                                                                                                                          ? [workout.instructions]
                                                                                                                                                                                                                              : defaultInstructions;

                                                                                                                                                                                                                                return (
                                                                                                                                                                                                                                    <div className="max-w-6xl mx-auto px-4 py-8">
                                                                                                                                                                                                                                          <Link
                                                                                                                                                                                                                                                  href="/"
                                                                                                                                                                                                                                                          className="inline-flex items-center gap-2 text-xs font-semibold text-neutral-400 hover:text-white mb-6 transition"
                                                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                                        <ArrowLeft className="w-4 h-4" /> Back to Workouts
                                                                                                                                                                                                                                                                              </Link>

                                                                                                                                                                                                                                                                                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 items-start">
                                                                                                                                                                                                                                                                                            {/* Left Side - Image */}
                                                                                                                                                                                                                                                                                                    <div className="bg-neutral-900 border border-neutral-800 rounded-2xl overflow-hidden">
                                                                                                                                                                                                                                                                                                              <img
                                                                                                                                                                                                                                                                                                                          src={workout.image || workout.illustration}
                                                                                                                                                                                                                                                                                                                                      alt={workout.name}
                                                                                                                                                                                                                                                                                                                                                  className="w-full h-auto max-h-[480px] object-cover"
                                                                                                                                                                                                                                                                                                                                                            />
                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                            {/* Right Side - Details */}
                                                                                                                                                                                                                                                                                                                                                                                    <div>
                                                                                                                                                                                                                                                                                                                                                                                              <div className="flex flex-wrap gap-1.5 mb-3">
                                                                                                                                                                                                                                                                                                                                                                                                          {workout.category?.map((cat, i) => (
                                                                                                                                                                                                                                                                                                                                                                                                                        <span
                                                                                                                                                                                                                                                                                                                                                                                                                                        key={i}
                                                                                                                                                                                                                                                                                                                                                                                                                                                        className="bg-neutral-800 text-[#ccff00] text-xs font-bold px-2.5 py-1 rounded uppercase"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {cat}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <h1 className="text-3xl font-black text-white uppercase tracking-tight mb-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {workout.name}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </h1>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p className="text-neutral-400 text-sm leading-relaxed mb-6">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {workout.description ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "A compound press that builds strength, muscular control, and core stability."}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {/* Key Specs Table/Panel */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="bg-neutral-900 border border-neutral-800 rounded-xl p-4 mb-6">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <h3 className="text-xs font-bold text-neutral-500 uppercase tracking-wider mb-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      KEY SPECS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="grid grid-cols-2 sm:grid-cols-3 gap-4 text-xs">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span className="text-neutral-500 block">EQUIPMENT</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span className="font-semibold text-white">{workout.equipment || "N/A"}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <span className="text-neutral-500 block">DIFFICULTY</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <span className="font-semibold text-white">{workout.difficulty || "Intermediate"}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span className="text-neutral-500 block">SETS</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span className="font-semibold text-white">{workout.sets || "4"}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <span className="text-neutral-500 block">REPS</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <span className="font-semibold text-white">{workout.reps || "6-8"}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span className="text-neutral-500 block">DURATION</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span className="font-semibold text-white">{workout.duration}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <span className="text-neutral-500 block">CALORIES</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <span className="font-semibold text-white">{workout.calories}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {/* Instructions */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="mb-6">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <h3 className="text-xs font-bold text-neutral-400 uppercase tracking-wider mb-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          INSTRUCTIONS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <ol className="space-y-2 text-xs text-neutral-300">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {instructionsList.map((step, idx) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <li key={idx} className="bg-neutral-900/60 p-3 rounded-lg border border-neutral-800 flex gap-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span className="font-bold text-[#ccff00]">{idx + 1}.</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span>{step}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </li>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </ol>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {/* Action Buttons */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="flex flex-col sm:flex-row gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onClick={() => addToPlan(workout)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    className="flex-1 bg-[#ccff00] text-black font-bold py-3 px-4 rounded-xl flex items-center justify-center gap-2 hover:opacity-90 transition text-xs uppercase tracking-wider"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <PlusCircle className="w-4 h-4" /> Add to today's plan
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onClick={() => addToSaved(workout)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  className="flex-1 bg-neutral-900 border border-neutral-700 text-white font-bold py-3 px-4 rounded-xl flex items-center justify-center gap-2 hover:border-[#ccff00] transition text-xs uppercase tracking-wider"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Bookmark className="w-4 h-4" /> Save for later
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }